using System;using System.IO;using System.Linq;using System.Net;using System.Text;using System.Text.RegularExpressions;using System.Collections.Generic;using System.Security.Cryptography;using System.Threading.Tasks;using System.Web.Script.Serialization;
public partial class TV {
 const string AerialReleases="https://github.com/pengchujin/aerial-tv/releases";
 public class AerialAsset {public string Name,Url,Digest;public long Size;}
 public static string AerialVariant(int sdk){if(sdk<14)throw new Exception("Aerial 不支持 Android 4.0 以前的系统");return sdk<21?"lite":"standard";}
 public static AerialAsset ParseAerialAsset(string json,string variant,out string version){
  if(!new[]{"standard","lite","guard"}.Contains(variant))throw new Exception("未知 Aerial 版本类型");
  var root=new JavaScriptSerializer{MaxJsonLength=4000000}.Deserialize<Dictionary<string,object>>(json);if(root==null||!root.ContainsKey("assets")||!root.ContainsKey("tag_name"))throw new Exception("GitHub 未返回有效发布信息，可能达到访问限额，请稍后重试");
  if((root.ContainsKey("draft")&&(bool)root["draft"])||(root.ContainsKey("prerelease")&&(bool)root["prerelease"]))throw new Exception("不自动安装草稿或预发布版");version=Convert.ToString(root["tag_name"]);if(!Regex.IsMatch(version,@"^[A-Za-z0-9._-]+$"))throw new Exception("发布版本号格式异常");
  foreach(var value in (System.Collections.IEnumerable)root["assets"]){var a=value as Dictionary<string,object>;if(a==null||Convert.ToString(a["name"])!="aerial-"+variant+".apk")continue;var item=new AerialAsset{Name=Convert.ToString(a["name"]),Url=Convert.ToString(a["browser_download_url"]),Size=Convert.ToInt64(a["size"]),Digest=a.ContainsKey("digest")?Convert.ToString(a["digest"]):""};Uri url;if(!Uri.TryCreate(item.Url,UriKind.Absolute,out url)||url.Scheme!="https"||url.Host!="github.com"||url.AbsolutePath!="/pengchujin/aerial-tv/releases/download/"+version+"/"+item.Name||url.Query!=""||url.UserInfo!=""||item.Size<=0||item.Size>100*1024*1024)throw new Exception("发布附件地址或大小异常，已停止下载");if(!Regex.IsMatch(item.Digest??"",@"^sha256:[a-fA-F0-9]{64}$"))throw new Exception("发布附件缺少有效 SHA256 校验信息，未执行安装");return item;}
  throw new Exception("最新发布没有 aerial-"+variant+".apk，请到发布页确认，未选择其他不明附件");
 }
 static HttpWebRequest AerialRequest(string url){var r=(HttpWebRequest)WebRequest.Create(url);r.UserAgent="XiaZheTeng-TVStudio/3.4";r.Timeout=30000;r.ReadWriteTimeout=30000;r.Accept="application/vnd.github+json";return r;}
 async Task<string> AerialLatest(){return await Task.Run(()=>{ServicePointManager.SecurityProtocol|=SecurityProtocolType.Tls12;using(var r=AerialRequest("https://api.github.com/repos/pengchujin/aerial-tv/releases/latest").GetResponse())using(var s=r.GetResponseStream())using(var b=new MemoryStream()){byte[] v=new byte[32768];int n;while((n=s.Read(v,0,v.Length))>0){if(b.Length+n>4000000)throw new Exception("发布信息过大");b.Write(v,0,n);}return Encoding.UTF8.GetString(b.ToArray());}});}
 public static void VerifyAerialFile(string file,AerialAsset asset){if(new FileInfo(file).Length!=asset.Size)throw new Exception("下载不完整，文件大小不符");using(var sha=SHA256.Create())using(var stream=File.OpenRead(file)){string h=BitConverter.ToString(sha.ComputeHash(stream)).Replace("-","").ToLowerInvariant();if(!string.Equals("sha256:"+h,asset.Digest,StringComparison.OrdinalIgnoreCase))throw new Exception("SHA256 校验不符，未执行安装");}}
 async Task<string> DownloadAerial(AerialAsset asset,string version){string dir=Data+"/downloads/aerial/"+version;Directory.CreateDirectory(dir);string dest=dir+"/"+asset.Name,temp=dest+"."+Guid.NewGuid().ToString("N")+".part";await Task.Run(()=>{try{using(var response=AerialRequest(asset.Url).GetResponse()){var u=response.ResponseUri;if(u.Scheme!="https"||!(u.Host=="github.com"||u.Host=="release-assets.githubusercontent.com"||u.Host=="objects.githubusercontent.com"))throw new Exception("下载跳转至非官方附件服务器，已停止");using(var src=response.GetResponseStream())using(var dst=File.Create(temp)){byte[] b=new byte[65536];int n,last=-1;long total=0;var clock=System.Diagnostics.Stopwatch.StartNew();while((n=src.Read(b,0,b.Length))>0){CheckCancelled();total+=n;if(total>asset.Size)throw new Exception("附件大于发布声明大小");dst.Write(b,0,n);int p=(int)(total*100/asset.Size)/10;if(p!=last){last=p;Report("下载 Aerial "+(p*10)+"% · "+(total/1048576.0/Math.Max(.1,clock.Elapsed.TotalSeconds)).ToString("F1")+" MB/s");}}}}VerifyAerialFile(temp,asset);if(File.Exists(dest))File.Delete(dest);File.Move(temp,dest);}finally{if(File.Exists(temp))File.Delete(temp);}});return dest;}
 public static void CheckAerialMetadata(string dump,string variant,int sdk,string abi){string expected=variant=="lite"?"app.orchard.tv.lite":"app.orchard.tv";var m=Regex.Match(dump,@"^package: name='([^']+)'",RegexOptions.Multiline);if(!m.Success||m.Groups[1].Value!=expected)throw new Exception("下载的 APK 包名不符，已停止安装");m=Regex.Match(dump,@"^sdkVersion:'(\d+)'",RegexOptions.Multiline);if(!m.Success||int.Parse(m.Groups[1].Value)>sdk)throw new Exception("APK 最低 Android 版本高于电视系统");var native=Regex.Match(dump,@"^native-code:\s*(.*)$",RegexOptions.Multiline);if(native.Success){var supported=new HashSet<string>(abi.Split(',').Select(x=>x.Trim()));bool compatible=Regex.Matches(native.Groups[1].Value,@"'([^']+)'").Cast<Match>().Any(x=>supported.Contains(x.Groups[1].Value));if(!compatible)throw new Exception("APK 的 CPU 架构与电视不兼容");}}
 async Task<string> FetchAerial(string release,string variant,int sdk,string abi){string version;var asset=ParseAerialAsset(release,variant,out version);Report("最新 Aerial："+version+" / "+variant+" · Android API "+sdk+" · "+abi);string file=await DownloadAerial(asset,version);string dump=await ProcessRun(Root+"tools/aapt.exe","dump badging "+Q(file),30000);CheckAerialMetadata(dump,variant,sdk,abi);var meta=await InspectApk(file);if(meta.Error!=null)throw new Exception(meta.Error);Report("软件："+meta.Name+" · 包名："+meta.Package+" · 版本："+meta.Version+" · SHA256 校验通过");return file;}
 void InstallAerial(){if(serial=="")throw new Exception("请先连接电视");Run(async()=>{cancellableTask=true;CheckCancelled();int sdk;if(!int.TryParse((await Shell("getprop ro.build.version.sdk")).Trim(),out sdk))throw new Exception("无法读取电视 Android 版本，未猜测安装");string variant=AerialVariant(sdk),abi=(await Shell("getprop ro.product.cpu.abilist")).Trim();if(abi=="")abi=(await Shell("getprop ro.product.cpu.abi")).Trim();string release=await AerialLatest();string file=await FetchAerial(release,variant,sdk,abi);var info=await InspectApk(file);CheckCancelled();cancellableTask=false;if(!Confirm("在线安装 Aerial\n软件："+info.Name+"\n包名："+info.Package+"\n版本："+info.Version+"\n电视："+serial+"\n覆盖安装会保留应用设置。继续？"))return;string result;try{result=await Adb("install -r "+Q(file));}catch(Exception ex){result=ex.Message;}if(!Regex.IsMatch(result,@"\bSuccess\b")){if(variant!="standard"||!Regex.IsMatch(result,"INSTALL_FAILED_USER_RESTRICTED|not allowed.*(?:home|launcher)|不允许.*桌面",RegexOptions.IgnoreCase)||!Confirm("standard 安装被电视限制：\n"+result+"\n是否改用官方 guard 兼容版？不会自动修改系统安全设置。"))throw new Exception(result);file=await FetchAerial(release,"guard",sdk,abi);result=await Adb("install -r "+Q(file));if(!Regex.IsMatch(result,@"\bSuccess\b"))throw new Exception(result);}
  if(!(await Shell("pm path "+info.Package)).Contains("package:"))throw new Exception("安装后未找到 Aerial");newLauncher=info.Package;File.WriteAllText(DeviceDir+"/new-launcher.txt",newLauncher);await Scan();await RefreshHomes();Show("步骤2");Report("Aerial 安装成功。请在电视上打开并设置默认桌面；守护版需按 Aerial 引导启用桌面守护，不自动授予额外权限。");});}
}
